"""Reproduce all delivered parameter estimates and model records.
Run exploratory_derivatives.py, identify.py, extend.py, multistart.py,
joint_fit.py, crossvalidate.py, residual_diagnostics.py, nonlinear_restoring.py,
and fit_restoring.py to reproduce screening and auxiliary diagnostics.
This script needs only candidate_config.json (recorded initial guesses),
extended_identify.py, identify.py, joint_fit.py and the two supplied CSVs.
It repeats the actual final least-squares fit, not merely copying estimates.
"""
from joint_fit import *
from pathlib import Path

configs=json.load(open('candidate_config.json'))

def parameter(name,value,unit,description):
 return {'name':name,'value':float(value),'unit':unit,'type':'fitted','description':description}


def build(row):
 k=row['kind'];p=row['p'];label=row['label']
 drive='a*u - g*sin(theta)'
 if k==5: drive='a*u - g*sin(theta)*(1 + h*cos(theta))'
 if k==6: drive='a*us*tanh(u/us) - g*sin(theta)'
 pars=[parameter('a',p[0],'rad/(s^2 V)','`a` is the positive motor acceleration gain, estimated jointly by the final open-loop angle least-squares fit.'),parameter('g',p[1],'rad/s^2','`g` is the positive nominal restoring acceleration amplitude, estimated jointly by the final open-loop angle least-squares fit.'),parameter('b',p[2],'1/s','`b` is the positive viscous acceleration coefficient (or its unmodulated value in AngleDamping), estimated jointly by the final open-loop angle least-squares fit.'),parameter('c',p[3],'rad/s^2','`c` is the positive moving-friction acceleration magnitude (reference value when modulated, high-speed limit in StribeckStiction), estimated jointly by the final open-loop angle least-squares fit.')]
 if k==11:
  pars.append(parameter('k',p[4],'1/s','`k` is the positive near-rest friction relaxation rate in the clipped-torque model, estimated jointly by the final open-loop angle least-squares fit.'))
 else:
  pars.append(parameter('v',p[4],'rad/s','`v` is the positive speed regularization scale, estimated jointly by the final open-loop angle least-squares fit; the lower bound prevents excessively stiff numerical dynamics.'))
 if k in (3,5,11):
  pars.append(parameter('h',p[5],'-', {3:'`h` is the logarithmic cosine modulation of damping, estimated jointly by the final open-loop angle least-squares fit.',5:'`h` is the relative cosine modulation of restoring torque; it supplies the second harmonic, estimated jointly by the final open-loop angle least-squares fit.',11:'`h` is the logarithmic cosine modulation of the friction limit, estimated jointly by the final open-loop angle least-squares fit.'}[k]))
 if k==2:
  pars.append(parameter('s',p[5],'rad/s^2','`s` is the nonnegative low-speed friction excess and additional static threshold, estimated jointly by the final open-loop angle least-squares fit.'))
  pars.append(parameter('ws',p[6],'rad/s','`ws` is the positive Gaussian friction-decay speed, estimated jointly by the final open-loop angle least-squares fit.'))
 if k==6:
  pars.append(parameter('us',p[5],'V','`us` is the positive motor saturation voltage scale, estimated jointly by the final open-loop angle least-squares fit.'))
 damp='b*omega' if k!=3 else 'b*exp(h*cos(theta))*omega'
 friction='c*tanh(omega/v)'
 if k==2:friction='(c + s*exp(-(omega/ws)**2))*tanh(omega/v)'
 limit='c + s' if k==2 else 'c'
 if k==0:expr=f'({drive}) - {damp} - {friction}'
 elif k==11:expr=f'({drive}) - b*omega - Min(Max(({drive}) + k*omega, -c*exp(h*cos(theta))), c*exp(h*cos(theta)))'
 else:expr=f'({drive}) - {damp} - {friction} - (1 - tanh(omega/v)**2)*Min(Max(({drive}), -({limit})), ({limit}))'
 names=[p['name'] for p in pars];units=[p['unit'] for p in pars]
 starts='; '.join(f'`{name} = {val:.15g}`'+(' '+unit if unit!='-' else '') for name,val,unit in zip(names,row['start'],units))
 bounds_text='; '.join(f'`{lo:.15g} <= {name} <= {hi:.15g}`'+(' '+unit if unit!='-' else '') for name,lo,hi,unit in zip(names,*bounds[k],units))
 method=("Bound-constrained nonlinear least squares, using `scipy.optimize.least_squares` with the trust-region reflective algorithm (`method = 'trf'`), linear residual loss, Jacobian scaling (`x_scale = 'jac'`), forward two-point finite differences and `diff_step = 0.0001`. The maximum number of residual evaluations was `max_nfev = 400`; the three stopping tolerances were `ftol = 1e-8`, `xtol = 1e-8` and `gtol = 1e-8`. All parameters in this file were fitted together in this final step. The initial guesses were "+starts+". They came from the earlier train-only simulation fit of this same family, selected by lowest training sum of squares; that stage was initialized by the physical moving-regime regression, not by random search. The bounds were "+bounds_text+". Positive coefficients enforce the torque and dissipation signs; the finite bounds on modulation and speed parameters avoid extreme extrapolation and excessive RK4 stiffness. No seed applies: the procedure is deterministic. The final estimate shown is the lower-cost result of two recorded starting points for this family; `candidate_config.json` records the winning starting point and `joint_results.json` records both fits. Model simulation uses our `simulate` function compiled with Numba, classical RK4 at `TS = 0.01` s and zero-order-held logged `u`. No measured states are substituted after initialization. The angle-only objective matches the scored variable and avoids treating centrally differentiated encoder noise as exact force measurements. The algorithm is a local optimizer; global optimality is not claimed. The optimization method is documented in the SciPy `least_squares` API; the record here specifies the actual settings, rather than relying on defaults alone.")
 baseinterpret=("The states are `theta` in rad and `omega` in rad/s; the exogenous input is `u` in V. The equation `dtheta = omega` enforces kinematics. For discussion only, define `drive = "+drive+"` in rad/s^2; it is expanded directly in the delivered expression, not an extra state. The term `a*u` represents voltage-proportional motor acceleration except where explicitly saturated. The term `-g*sin(theta)` represents pendulum-like restoring torque per inertia. The term `-b*omega` represents viscous damping except where explicitly modulated. Only normalized acceleration coefficients are identifiable: inertia and physical torques are not separately estimated. ")
 staticinterp=("The moving friction term is `-"+friction+"` in rad/s^2. Define `gate = 1-tanh(omega/v)**2`, a dimensionless near-rest weight. The term `-gate*Min(Max(drive, -("+limit+")), ("+limit+"))` cancels subthreshold applied acceleration exactly at rest, and fades away during motion. At `omega = 0` rad/s it reduces to `drive - Min(Max(drive, -("+limit+")), ("+limit+"))`; therefore a continuum of exact resting equilibria exists when `Abs(drive) <= "+limit+"` in rad/s^2. This is a memoryless analytic sticking approximation, not a separately identified elastic friction state. ")
 origins="The shared pendulum, linear motor and viscous terms were chosen from physical torque balance. Moving-row bounded linear least squares on `Abs(omega) > 0.5` rad/s in `data/train.csv` supplied initial coefficients; `exploratory_derivatives.py` records that screening. Initial simulation fits used the 13 training trajectories; independent initial comparisons used all 3 validation trajectories. Smooth Coulomb, analytic stiction, Stribeck, angle-modulated damping/friction, restoring harmonics, motor saturation and asymmetric moving friction were screened; multistart fits checked stopping-event local minima. No genetic symbolic regression was run. The proposed structures, rather than black-box predictors, were compared directly by open-loop simulation. "
 limitations="The supplied records are short, mostly at rest in free response, and do not identify motor current, inertia, presliding displacement, temperature or trajectory-to-trajectory changes. The first logged velocity is imposed even when numerical differentiation makes it an uncertain initial condition. A memoryless law cannot describe full friction hysteresis. Parameter values are effective coefficients for these experiments, not independently measured material constants. The actual training voltage range was approximately `-4.945 <= u <= 3.953` V, so motor behavior near the required extremes is extrapolation. Model selection used the supplied data, including grouped holdout diagnostics, and is not an untouched external test. In the final fit the former validation file was reused, so its final RMSE must not be called independent validation performance. "
 families={0:'Regularized Coulomb-plus-viscous pendulum/DC-motor torque balance.',2:'Stribeck-plus-viscous friction with a Gaussian speed-decay term and analytic static-friction cancellation.',3:'Nonlinear pendulum with positive angle-modulated viscous damping and analytic static-friction cancellation.',5:'Two-harmonic nonlinear restoring torque with Coulomb-plus-viscous friction and analytic static-friction cancellation.',6:'Monotone saturating actuator with nonlinear pendulum dynamics and analytic static-friction cancellation.',11:'Memoryless torque-limited friction relaxation with an angle-dependent positive friction limit.'}
 family=families[k]+" These are physically motivated grey-box ordinary differential equations, not an exact implementation of a named hysteretic friction model. General context, cited from memory without a successfully fetched source: B. Armstrong-Helouvry, P. Dupont and C. Canudas de Wit, 'A survey of models, analysis tools and compensation methods for the control of machines with friction', Automatica 30(7), 1083-1138 (1994). The particular cancellation or clipping expression here was constructed for this task and is not attributed to that survey."
 interpretation=baseinterpret
 if k==0:
  interpretation+="The term `-c*tanh(omega/v)` is smooth Coulomb friction, approaching `-c*sign(omega)` away from rest. It retains positive damping near zero but does not give exact stiction. "
  origins+="This deliberately minimal family was retained as a predictive reference because it had the lowest independent initial validation RMSE among the first eight screened forms; it sacrifices exact sticking. The `tanh` replacement was chosen for continuous, stable evaluation rather than inferred by symbolic search. "
  limitations+="It creeps toward zero under subthreshold restoring torque and should not be used to infer a static stick band; the short observation horizons can conceal that defect. "
 elif k==11:
  interpretation+="Define `limit = c*exp(h*cos(theta))` in rad/s^2. The clipped friction term is `-Min(Max(drive+k*omega, -limit), limit)`. Inside the unsaturated interval the total acceleration is `-(b+k)*omega`; outside it the friction torque is capped. At rest, subthreshold acceleration is exactly canceled. The positive exponential limit allows angle-related modulation without sign reversal; no changing normal-force mechanism is established by these data. "
  origins+="Moving-regime residuals had correlations with `cos(theta)*sign(omega)` and `cos(theta)*omega`; this motivated positive cosine modulation rather than an unconstrained friction coefficient that could become negative. The clipped-torque relaxation law was constructed as a numerically well-conditioned alternative to a discontinuous sign law. Its relaxation-rate bounds keep the near-rest scalar damping within the RK4 stability interval at the specified step. "
  limitations+="The angle modulation may absorb differentiation and load effects rather than true position-dependent dry friction. The relaxation rate and friction limit are correlated around stops. "
 else:
  interpretation+=staticinterp
  if k==5:
   interpretation+="The restoring term is `-g*sin(theta)*(1+h*cos(theta))`, equivalent to adding `-(g*h/2)*sin(2*theta)`. The fitted dimensionless `h` changes stiffness between small and large angles without destroying restoring sign because `Abs(h) < 1`. It is an empirical torque-shape correction, not evidence for a particular extra spring. "
   origins+="The one-harmonic models had structured errors on large-angle free responses and angle-related acceleration residuals. This motivated the second restoring harmonic. A subsequent residual-driven exponential asymmetry, `-g*sin(theta)*(1+h*cos(theta))*exp(q*sin(theta))` with dimensionless `q`, was actually fitted but rejected: its grouped holdout RMSE was about `0.07472` rad versus `0.07191` rad for the simpler harmonic structure over all supplied trajectories. The static cancellation operator was designed to preserve resting equilibria, not discovered by unrestricted symbolic search. "
   limitations+="Large-angle transient fit and terminal stick position still vary by trajectory; fitting one effective restoring shape cannot resolve all experiment-specific offsets. "
  if k==2:
   interpretation+="The positive term `s*exp(-(omega/ws)**2)` raises low-speed moving friction above the high-speed level `c`; the static cancellation limit is `c+s`. The data estimate a broad decay, so the dynamic curve can also behave as nonlinear damping over the observed speeds. "
   origins+="The Gaussian speed-decay term is the physically motivated Stribeck family listed before fitting. It was retained because grouped trajectory holdout slightly improved over the smooth-friction baseline and because it preserves sticking, not because a static-vs-dynamic friction difference was independently measured. "
   limitations+="The estimates reach the lower bound for `c` and the upper bound for `ws`; the separation of high-speed friction, decay speed and viscous damping is weakly identified. This candidate is a defensible empirical friction curve, but not a precise identification of a Stribeck mechanism. "
  if k==3:
   interpretation+="The viscous term is `-b*exp(h*cos(theta))*omega`; it is dissipative at every angle. The exponential is a mathematical modulation of speed damping, not proof of a mechanical cause. "
   origins+="The moving derivative residuals supported screening `cos(theta)*omega`; exponentiation was chosen to preserve positive damping globally. Subsequent open-loop fitting improved training trajectories but was less convincing than the recommended harmonic model in grouped holdout. It is retained as a distinct load-modulation hypothesis rather than another coefficient perturbation. "
   limitations+="The cosine damping correction may stand in for correlated angle/speed sampling; it is not independently identified as bearing damping. "
  if k==6:
   interpretation+="Replace the linear voltage torque by `a*us*tanh(u/us)`, in rad/s^2. Its input derivative is nonnegative at every voltage; it approaches bounded torque at large voltage. The saturation is empirical and does not introduce a motor-current state. "
   origins+="The initial voltage-cubic screening gave negligible derivative-fit improvement, but open-loop motor saturation improved one driven training trajectory. A positive-scale `tanh` actuator was tested instead of a cubic because it remains monotone across the entire required voltage interval. This candidate preserves a distinct actuator nonlinearity for evaluation, though the grouped holdout did not favor it over the recommendation. "
   limitations+="Observed voltages are mostly within the nearly linear portion; the inferred saturation scale is extrapolative and may absorb omitted motor dynamics or voltage timing effects. "
 r2=("All coefficients controlling motor gain, damping and friction magnitude are positive. At `omega = 0` rad/s and `u = 0` V, the unbalanced restoring drive has sign opposite `theta` on `-pi <= theta <= pi` rad; clipping can only reduce its magnitude. Thus `domega*theta <= 0`. " if k!=0 else "At `omega = 0` rad/s and `u = 0` V the acceleration is `-g*sin(theta)`, so `domega*theta <= 0` on `-pi <= theta <= pi` rad. ")
 r3=("For fixed `theta` and `omega`, clipping is nondecreasing with slope between zero and one, and the gate is between zero and one; hence the complete input map is nondecreasing. Exact stiction necessarily creates flat input intervals. " if k not in (0,11) else ("The input map is linear with positive gain `a`. " if k==0 else "The derivative of the clipped term with respect to the drive is between zero and one, so the complete input map is nondecreasing, including flat intervals inside the stick band. "))
 interpretation+=r2+r3
 combined=(2*row['cost']/4698)**.5
 limitations+=f"The all-data refit angle RMSE is `{combined:.6f}` rad over 4698 predicted samples; the training-file RMSE is `{row['train']['rmse']:.6f}` rad and the reused-validation-file RMSE is `{row['val_reused']['rmse']:.6f}` rad. Conditional leave-one-trajectory-out RMSE is `{row['loto_rmse']:.6f}` rad over the same sample count: each of the 16 supplied trajectories was omitted in turn and simulated from its first logged state, with fit parameters reestimated on the other 15. These fits were warm-started from the full-data estimate and are diagnostic rather than nested model-selection validation."
 return {'expressions':{'dtheta':'omega','domega':expr},'parameters':pars,'estimation':{'criterion':'Minimize the sum of squared open-loop angle residuals `theta_simulated - theta_measured`, in rad, over every sample after the first within each supplied trajectory. Every predicted sample receives equal weight; there is no per-trajectory normalization and no acceleration penalty. This matches the evaluation metric and lets free responses constrain stopping rather than letting their numerous zero derivatives dominate a derivative regression.','data':'Final estimation uses `data/train.csv`, all 13 trajectories and 3522 rows, and `data/val.csv`, all 3 trajectories and 1192 rows. There are 4714 rows in total and 4698 scored residuals after excluding each trajectory initial sample. No moving or resting rows are discarded in the final simulation fit. Each trajectory starts from its own first logged `theta` and `omega`; recorded `u` is held constant over each `TS = 0.01` s interval. The former validation file was deliberately reused for the final fit after initial train-only model comparisons, to use the limited available transient information; its refit scores are not held-out validation.','method':method,'script':'fit_candidates.py'},'discussion':{'family':family,'interpretation':interpretation,'origin':origins,'limitations':limitations}}

if __name__=='__main__':
 Path('models').mkdir(exist_ok=True)
 for row in configs:
  sol=fit(row['kind'],row['start'],data=all_data,max_nfev=400)
  row['p']=sol.x.tolist();row['cost']=float(sol.cost)
  row['train']=score(sol.x,row['kind'],train);row['val_reused']=score(sol.x,row['kind'],val)
  json.dump(build(row),open('models/'+row['label']+'.json','w'),indent=2)
  print(row['label'],sol.x,'cost',sol.cost,flush=True)
 pool={'order':[r['label'] for r in configs],'recommended':'HarmonicStiction','reason':'Recommend HarmonicStiction: it combines an exactly stationary stick band with a bounded, sign-preserving second-harmonic restoring correction. Its conditional leave-one-trajectory-out angle RMSE was `0.071908` rad over all 4698 predicted samples, lower than the other delivered structures under the same diagnostic. This is not a hidden-test result or nested model-selection validation. The simpler smooth Coulomb comparator had better initial independent validation performance but does not maintain true sticking; the recommendation favors both trajectory robustness and the intended physics. All final coefficients use both supplied files, so final validation-file errors are explicitly labeled reused-data diagnostics. See `identification_report.md`, `crossvalidation_results.json` and each candidate record for qualifications.'}
 json.dump(pool,open('models/pool.json','w'),indent=2)
